//! Reads the encrypted chart bundle compiled into the executable.
//!
//! Layout of `charts.bin`:
//!   "OPB1" | u32 header length | header entry | chart entries...
//! Every entry is `nonce (12 bytes) | ChaCha20(zlib(data))`.
//! Nothing is ever written to disk; charts are decrypted in memory on demand.

use std::collections::HashMap;
use std::io::Read;

use chacha20::cipher::{KeyIvInit, StreamCipher};
use chacha20::ChaCha20;
use serde::Deserialize;

// Generated by build.rs from private/ (not in the public repo). See README.
include!(concat!(env!("OUT_DIR"), "/key.rs"));

static BLOB: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/charts.bin"));

#[derive(Debug, Clone, Deserialize)]
pub struct ChartRef {
    pub id: String,
    pub kind: String, // "area" | "ground" | "SID" | "STAR"
    #[serde(default)]
    pub region: Option<String>,
    #[serde(default)]
    pub icao: Option<String>,
    #[serde(default)]
    pub rw: Option<String>,
    pub label: String,
    #[serde(default)]
    pub title: Option<String>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Region {
    pub id: String,
    pub name: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Runway {
    pub ident: String,
    pub course: String,
    pub len_ft: Option<f64>,
    pub wid_ft: Option<f64>,
    pub thr_ft: Option<f64>,
    #[serde(default)]
    pub measured: bool,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Procedure {
    pub kind: String,
    pub name: String,
    pub rw: String,
    pub route: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Airport {
    pub icao: String,
    pub name: String,
    pub region: String,
    pub elev_ft: Option<f64>,
    #[serde(default)]
    pub freqs: String,
    #[serde(rename = "procSrc")]
    pub proc_src: Option<String>,
    pub src: Option<String>,
    pub runways: Vec<Runway>,
    pub procs: Vec<Procedure>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Meta {
    pub regions: Vec<Region>,
    pub airports: Vec<Airport>,
    #[serde(default)]
    pub airac: String,
}

#[derive(Debug, Deserialize)]
struct Header {
    charts: Vec<ChartRef>,
    meta: Meta,
    offsets: HashMap<String, (usize, usize)>,
}

pub struct Bundle {
    pub charts: Vec<ChartRef>,
    pub meta: Meta,
    offsets: HashMap<String, (usize, usize)>,
    body_start: usize,
}

fn key() -> [u8; 32] {
    let mut k = [0u8; 32];
    for i in 0..32 {
        k[i] = KA[i] ^ KB[i];
    }
    k
}

fn open_entry(entry: &[u8]) -> Result<Vec<u8>, String> {
    if entry.len() < 12 {
        return Err("damaged chart data".into());
    }
    let (nonce, body) = entry.split_at(12);
    let mut buf = body.to_vec();
    let k = key();
    let mut cipher = ChaCha20::new(&k.into(), nonce.try_into().map_err(|_| "bad nonce")?);
    cipher.apply_keystream(&mut buf);
    let mut out = Vec::new();
    flate2::read::ZlibDecoder::new(&buf[..])
        .read_to_end(&mut out)
        .map_err(|_| "damaged chart data".to_string())?;
    Ok(out)
}

impl Bundle {
    pub fn load() -> Result<Self, String> {
        if BLOB.starts_with(b"OPB0") {
            return Err("This build doesn't include the chart bundle.\n\nDownload the official OpenPlates release from GitHub, \nor put your own bundle in private/ and rebuild (see README).".into());
        }
        if BLOB.len() < 8 || &BLOB[..4] != b"OPB1" {
            return Err("chart bundle missing or damaged".into());
        }
        let head_len = u32::from_le_bytes(BLOB[4..8].try_into().unwrap()) as usize;
        let head = open_entry(&BLOB[8..8 + head_len])?;
        let h: Header = serde_json::from_slice(&head).map_err(|e| format!("bad index: {e}"))?;
        Ok(Self {
            charts: h.charts,
            meta: h.meta,
            offsets: h.offsets,
            body_start: 8 + head_len,
        })
    }

    /// Decrypts one chart's SVG into memory.
    pub fn svg(&self, id: &str) -> Result<Vec<u8>, String> {
        let &(pos, len) = self.offsets.get(id).ok_or("chart not found")?;
        let a = self.body_start + pos;
        open_entry(&BLOB[a..a + len])
    }
}
